/**
 * M11 Phase 2 — "what next?" chips shown after an agent answer.
 *
 * DETERMINISTIC (ADR-0049): derived from the run's artifacts + tool calls, not
 * generated by the model. Zero extra model call, so it is free, instant, and
 * unit-testable. The renderer maps each `action` to either opening an artifact
 * or pre-filling the composer with a follow-up instruction (never auto-sent —
 * the scholar reviews it first).
 *
 * Pure — no runtime globals.
 */

export type RecommendationAction =
  | "open-artifact"
  | "insert-footnote"
  | "typeset-print"
  | "build-indexes"
  | "transcript-to-chapter"
  | "compare-variants"
  | "build-spreadsheet";

export interface RecommendedAction {
  id: string;
  /** i18n key for the chip label (`agent.rec.<action>`). */
  labelKey: string;
  action: RecommendationAction;
  /** For `open-artifact`. */
  artifactId?: string;
}

export interface RecommendContext {
  artifacts: Array<{ id: string; type: string }>;
  toolCalls: Array<{ name: string }>;
  mode: "ask" | "plan" | "auto";
  /** Desktop project folder open (web has no `.docx` chapters). */
  hasProjectFolder: boolean;
  /** The artifact the stage is already showing — no "open" chip for it. */
  activeArtifactId?: string | null;
}

const CITABLE = new Set([
  "search_corpus", "search_shamela", "read_shamela_page", "query_tafseer",
  "search_hadith", "grade_hadith", "lookup_narrator", "lookup_lexicon",
  "search_repositories", "research_topic", "search_persian_poetry",
  "lookup_urdu_verse", "jkhssn_takhrij",
]);

const MAX = 4;

export function recommendActions(ctx: RecommendContext): RecommendedAction[] {
  const out: RecommendedAction[] = [];
  const called = new Set(ctx.toolCalls.map((t) => t.name));
  const canWrite = ctx.mode !== "ask" && ctx.hasProjectFolder;

  // Open an artifact the answer produced that the stage is not already showing.
  for (const a of ctx.artifacts) {
    if (a.id !== ctx.activeArtifactId) {
      out.push({ id: `open-${a.id}`, labelKey: "agent.rec.open_artifact", action: "open-artifact", artifactId: a.id });
      break;
    }
  }

  // Retrieved sources but never footnoted them (write-capable only).
  const retrieved = [...called].some((n) => CITABLE.has(n));
  if (retrieved && canWrite && !called.has("insert_footnote")) {
    out.push({ id: "insert-footnote", labelKey: "agent.rec.insert_footnote", action: "insert-footnote" });
  }

  // Wrote or drafted a chapter → offer the print layout / indexes next.
  if (canWrite && (called.has("create_chapter") || called.has("draft_section") || called.has("run_task"))) {
    if (!called.has("typeset_print_ready")) {
      out.push({ id: "typeset-print", labelKey: "agent.rec.typeset_print", action: "typeset-print" });
    }
    if (!called.has("build_scholarly_indexes")) {
      out.push({ id: "build-indexes", labelKey: "agent.rec.build_indexes", action: "build-indexes" });
    }
  }

  // Transcribed a recording → turn it into a chapter.
  if (canWrite && called.has("transcribe_media") && !called.has("create_chapter")) {
    out.push({ id: "transcript-to-chapter", labelKey: "agent.rec.transcript_to_chapter", action: "transcript-to-chapter" });
  }

  // A takhrīj that found variants → compare their matns.
  if (called.has("jkhssn_takhrij") && !called.has("compare_manuscript_variants")) {
    out.push({ id: "compare-variants", labelKey: "agent.rec.compare_variants", action: "compare-variants" });
  }

  // M12 Phase D — a zakat/farā'iḍ result (a table artifact) → offer to turn
  // it into a live-formula workbook (closes ADR-0049's deferred xlsx chip,
  // now that build_spreadsheet's table->file path actually works).
  if (canWrite && (called.has("calculate_zakat") || called.has("calculate_faraid")) && !called.has("build_spreadsheet")) {
    out.push({ id: "build-spreadsheet", labelKey: "agent.rec.build_spreadsheet", action: "build-spreadsheet" });
  }

  return out.slice(0, MAX);
}

/** The follow-up instruction each non-artifact chip pre-fills (renderer-side). */
export const RECOMMENDATION_PROMPT: Record<Exclude<RecommendationAction, "open-artifact">, string> = {
  "insert-footnote": "ابھی جو مآخذ ملے ہیں، اُن سے متعلقہ مقامات پر حوالہ جات (فٹ نوٹ) داخل کریں۔",
  "typeset-print": "/typeset-print",
  "build-indexes": "/generate-indexes",
  "transcript-to-chapter": "اس ٹرانسکرپٹ کو ایک نئے باب کی صورت میں مرتب کریں۔",
  "compare-variants": "اس روایت کے مختلف طرق کے متون کا تقابل کر کے فرق واضح کریں۔",
  "build-spreadsheet": "اس نتیجے کو لائیو فارمولوں کے ساتھ ایکسل شیٹ میں تبدیل کریں (export/ فولڈر میں)۔",
};
